@-moz-document regexp("https://www.google."),
regexp("https://(www|encrypted|images).google.(com|co.[a-z]{2}|com.[a-z]{2}|[a-z]{2})?/.*") {
    /*Animations for reference*/
    @keyframes fadeInDown {
        0% {
            transform: translate(0px, -20px);
            opacity: 0;
        }
        100% {
            transform: translate(0px, 0px);
            opacity: 1;
        }
    }
    @keyframes fadeInRight {
        0% {
            transform: translate(-20px, 0px);
            opacity: 0;
        }
        100% {
            transform: translate(0px, 0px);
            opacity: 1;
        }
    }
    @keyframes fadeInUp {
        0% {
            transform: translate(0px, 20px);
            opacity: 0;
        }
        100% {
            transform: translate(0px, 0px);
            opacity: 1;
        }
    }
    @keyframes fadeInLeft {
        0% {
            transform: translate(20px, 0px);
            opacity: 0;
        }
        100% {
            transform: translate(0px, 0px);
            opacity: 1;
        }
    }
    @keyframes slideInDown {
        0% {
            transform: translateY(-50%);
        }
        100% {
            transform: translateY(0);
        }
    }
    @keyframes put {
        0% {
            transform: scale(1.1, 1.1);
            opacity: 0;
        }
        100% {
            transform: scale(1, 1);
            opacity: 1;
        }
    }
    @keyframes openHoriz {
        0% {
            transform: scale(1, 0.8);
            opacity: 0;
        }
        100% {
            transform: scale(1, 1);
            opacity: 1;
        }
    }
    @keyframes openVert {
        0% {
            transform: scale(0.8, 1);
            opacity: 0;
        }
        100% {
            transform: scale(1, 1);
            opacity: 1;
        }
    }
    @keyframes zoomCenter {
        0% {
            transform: scale(0.9, 0.9);
            opacity: 0;
        }
        100% {
            transform: scale(1, 1);
            opacity: 1;
        }
    }
    @keyframes zoomTopCenter {
        0% {
            transform: translate(0px, -100px) scale(0.9, 0.7);
            opacity: 0;
        }
        100% {
            transform: translate(0px, 0px) scale(1, 1);
            opacity: 1;
        }
    }
    @keyframes zoomBottomCenter {
        0% {
            transform: translate(0px, 100px) scale(0.9, 0.7);
            opacity: 0;
        }
        100% {
            transform: translate(0px, 0px) scale(1, 1);
            opacity: 1;
        }
    }
    @keyframes rollLeft {
        0% {
            transform: rotate(5deg);
            opacity: 0;
        }
        100% {
            transform: rotate(0deg);
            opacity: 1;
        }
    }
    @keyframes rollRight {
        0% {
            transform: rotate(-5deg);
            opacity: 0;
        }
        100% {
            transform: rotate(0deg);
            opacity: 1;
        }
    }
    @keyframes fade {
        0% {
            opacity: 0;
        }
        100% {
            opacity: 1;
        }
    }
    @keyframes logoR {
        0% {
            transform: translateY(0px);
        }
        50% {
            transform: translateY(5px);
        }
        100% {
            transform: translateY(0px);
            opacity: 1;
        }
    }
}

/* ==UserStyle==
@name           chewyoogle
@namespace      chewyspace
@version        1.0.0
@description    Chewygum's Google
@author         https://www.github.com/chewygumxx
==/UserStyle== */

@-moz-document
url("https://www.google.com"),
url("https://www.google.com/search"),
regexp("https?://(www|encrypted|images|translate|accounts).google.(com|([a-z]{2}))(.[a-z]{2})?/(?!mobile|intl|alerts|shopping|finance|calendar|nexus|contacts|services|advanced_search|voice|maps|dashboard|settings|android|adsense|analytics|doodles|chrome|fonts|patents|translate_p).*"),
regexp("https://google\\..+") {
	:root {
		--base-0: #03030b;
		--base-1: #040512;
		--base-2: #060616;
		--base-3: #090a24;
		--base-4: #0b0c2d;
		--base-5: #141337;
		--base-6: #2d2857;

		--purp-dark:        #4e4581;
		--purp-subtle:      #806fc0;
		--purp-indigo-deep: #6161a3;
		--purp-indigo:      #7171d3;
		--purp-neon:        #7408ff;
		--purp-bright:      #b66ffd;
		--purp-white:       #b399ff;

		--blue-cornflower:  #5f95fa;
		--blue-cyan:        #43cfea;
		--blue:             #87afff;
		--blue-electric:    #66ccff;

		--domain:              var(--purp-indigo);
		--domain-subtitle:     var(--purp-indigo);
		--domain-subtitle-ext: var(--purp-indigo-deep);

		--link: var(--blue-electric);
		--link-visited: var(--purp-neon);

		--date: var(--purp-indigo-deep);

		--cool-white-0: #cad6ff;
		--cool-white-1: #e8e0ff;
	}

	:root {
