		--purp-pale:        #8874ed;
		--purp-bright:      #b66ffd;
		--purp-white:       #b399ff;

		--cool-white-0: #cad6ff;
		--cool-white-1: #e8e0ff;

	}

	@media (prefers-color-scheme: dark) { html[data-color="system"] {
		--primary-d2: var(--base-2); /* Default: #4d4d4d */  
		--primary-d1: var(--base-2); /* Default: #404040 */  
		--primary:    var(--base-0); /* Default: #333    */     
		--primary-l1: var(--base-1); /* Default: #2e2e2e */  
		--primary-l2: var(--base-1); /* Default: #2b2b2b */  

		--secondary-d1: var(--cool-white-0); /* Default: #b8b3b3 */  
		--secondary:    var(--cool-white-0); /* Default: #9f9999 */     
		--secondary-l1: var(--cool-white-0); /* Default: #867f7f */  
		--secondary-l2: var(--cool-white-0); /* Default: #6c6666 */  
		--secondary-f1: var(--cool-white-0); /* Default: #898585 */  
		--secondary-f2: var(--cool-white-0); /* Default: #747070 */  

		--accent-d2: var(--); /* Default: #524d4d */  
		--accent-d1: var(--); /* Default: #5f5a5a */  
		--accent:    var(--purp-reg); /* Default: #6c6666 */     
		--accent-l1: var(--); /* Default: #797272 */  
		--accent-l2: var(--); /* Default: #867f7f */  

		--error-d1: var(--red); /* Default: #b75c5c */  
		--error:    var(--red); /* Default: #9b4545 */     
		--error-l1: var(--red); /* Default: #783535 */  

		--shadow-color:   var(--); /* Default: #00000088 */  
		--slow-key-color: var(--); /* Default: #8c1818 */  
		--fast-key-color: var(--); /* Default: #448154 */  
		--effort-color:   var(--); /* Default: #2d4a86 */    

		--textinput__color:          var(--purp-subtle); /* Default: #9f9999 */ 
		--textinput--hit__color:     var(--purp-dark); /* Default: #747070 */ 
		--textinput--miss__color:    var(--red); /* Default: #9b4545 */
		--textinput--special__color: var(--purp-dark); /* Default: #696666 */

		--Name-color:         var(--purp-pale); /* Default: #d0cece */   
		--Value-color:        var(--blue-pale); /* Default: #867f7f */         
		--Value--more__color: var(--green); /* Default: #2a7e21 */  
		--Value--less__color: var(--red); /* Default: #a1464e */  

		--Chart-speed__color:      var(--); /* Default: #517460 */        
		--Chart-accuracy__color:   var(--); /* Default: #914331 */     
		--Chart-complexity__color: var(--); /* Default: #705282 */   
		--Chart-threshold__color:  var(--); /* Default: #834c67 */    
		--Chart-hist-h__color:     var(--); /* Default: #495074 */       
		--Chart-hist-m__color:     var(--); /* Default: #743939 */       
		--Chart-hist-r__color:     var(--); /* Default: #723a74 */       

		--KeyboardKey-pointer__color: var(--); /* Default: #4ba0f2 */  
		--pinky-zone-color:       var(--purp-dark); /* Default: #617a58 */            
		--ring-zone-color:        var(--purp-indigo-deep); /* Default: #76772d */             
		--middle-zone-color:      var(--purp-indigo); /* Default: #977831 */           
		--left-index-zone-color:  var(--purp-reg); /* Default: #5b6d66 */       
		--right-index-zone-color: var(--purp-pale); /* Default: #835d67 */      
		--thumb-zone-color:       var(--purp-subtle); /* Default: #854b44 */            

		--purp-dark:        #4e4581;
		--purp-subtle:      #806fc0;
		--purp-indigo-deep: #6161a3;
		--purp-indigo:      #7171d3;
		--purp-reg:         #7408c4;
		--purp-neon:        #7408ff;
		--purp-pale:        #8874ed;
		--purp-bright:      #b66ffd;
		--purp-white:       #b399ff;
		--syntax-keyword: var(--); /* Default: #5991cd */  
		--syntax-string:  var(--); /* Default: #72b172 */   
		--syntax-number:  var(--); /* Default: #b281d3 */   
		--syntax-comment: var(--); /* Default: #9f8484 */  
	}}


	:where(html), [data-preview-theme] {
		--background-color: var(--primary);
		--background-image: none;
		--text-color: var(--secondary);
